const names=['Properties','Leases','Lease Tenants','Charges','Payments','Credits','Returned Payments','Tasks'];const data={},sourceCounts={},paginationChecks={};for(const s of names){const d=$('Validate API - '+s).first().json;if(!d.complete||!Array.isArray(d.records)||d.records.length!==d.total)throw Error('Incomplete source: '+s);data[s]=d.records;sourceCounts[s]=d.total;paginationChecks[s]={pages:d.pages,complete:true,collectedAt:d.collectedAt};}
