const reversedIds=new Set(data['Returned Payments'].map(r=>r.leasePayment));const monthlyPayments=data.Payments.filter(p=>String(p.date).slice(0,7)===month&&p.date<=today);const paymentRows=monthlyPayments.map(p=>({id:p.id,date:p.date,leaseId:p.lease,amountReceived:money(p.amountReceived),depositStatus:p.depositStatus||'UNAVAILABLE',returnedPaymentLinked:reversedIds.has(p.id)})).sort((a,b)=>b.date.localeCompare(a.date));const depositCounts={};for(const p of paymentRows)depositCounts[p.depositStatus]=(depositCounts[p.depositStatus]||0)+1;
