const lines=['# DoorLoop rent and task snapshot',today+' | America/New_York | read-only live API','Complete source counts: '+Object.entries(sourceCounts).map(([k,v])=>k+' '+v).join('; '),'','## API-calculated overdue balances','These are DoorLoop lease.overdueBalance fields, not a reconstructed ledger. Amounts are account currency formatted as USD; verify the account currency and ledger before outreach.','Active leases with positive overdue balances: '+activeOverdue.length+'; other/inactive leases: '+otherOverdue.length+'; missing balance fields: '+missingBalances+'.','Collection-status conflicts requiring review: '+overdue.filter(l=>l.collectionStatus!=='OVERDUE').map(l=>label(l.leaseId)+' status '+l.collectionStatus+' but overdue '+usd(l.overdueBalance)).join('; '),'Active overdue total: '+usd(activeOverdue.reduce((s,l)=>s+l.overdueBalance,0))+'; other/inactive overdue total: '+usd(otherOverdue.reduce((s,l)=>s+l.overdueBalance,0)),...overdue.slice(0,50).map(l=>'- '+label(l.leaseId)+' | '+l.status+'/'+l.calculatedStatus+' | collection '+l.collectionStatus+' | overdue '+usd(l.overdueBalance)+' | total due '+usd(l.totalBalanceDue)),'','## Payment records this month through '+today,'Records: '+paymentRows.length+'; raw deposit statuses: '+JSON.stringify(depositCounts)+'. A payment record or DEPOSITED status alone does not establish bank settlement. Returned-payment references are flagged.',...paymentRows.slice(0,50).map(p=>'- '+p.date+' | '+label(p.leaseId)+' | amountReceived '+usd(p.amountReceived)+' | '+p.depositStatus+' | linked return '+p.returnedPaymentLinked),'Showing '+Math.min(paymentRows.length,50)+' of '+paymentRows.length+' payment records.','', '## Open task review','All task statuses: '+JSON.stringify(taskStatuses), 'Non-terminal tasks: '+openTasks.length+'; dated before today: '+datedOverdue.length+'. Historical/stale records require review; these are task due dates, not confirmed contractor appointments.',...taskRows.slice(0,50).map(t=>'- '+t.subject+' 